(()=>{function init(){const layers=[];for(const e of document.querySelectorAll('.modal,.first-run-flow,#feedback')){const d=document.createElement('dialog');d.className='ss-layer';d.id='layer-'+e.id;document.body.append(d);d.append(e);e.removeAttribute('role');e.removeAttribute('aria-modal');d.setAttribute('aria-labelledby',e.id==='feedback'?'feedback-title':e.getAttribute('aria-labelledby')||'');if(e.id==='feedback'){d.setAttribute('aria-describedby','feedback-message');d.addEventListener('click',ev=>{if(ev.target.closest('.btn-next')){e.classList.add('hidden');d.close()}},true);d.addEventListener('keydown',ev=>{if(ev.key==='Enter'){ev.preventDefault();ev.stopImmediatePropagation();e.querySelector('.btn-next')?.click()}},true)}d.addEventListener('cancel',ev=>{ev.preventDefault();if(e.id==='feedback')e.querySelector('.btn-next')?.click();else{const b=e.querySelector('.btn-close');if(b)b.click();else e.classList.add('hidden')}});layers.push({e,d})}function sync(){for(const{e,d}of layers){if(!e.classList.contains('hidden')&&!d.open)d.showModal();else if(e.classList.contains('hidden')&&d.open)d.close()}document.querySelectorAll('.home-hub-card').forEach(e=>e.remove());document.querySelectorAll('[style]').forEach(e=>{if(e.tagName==='HTML')return;const bg=e.style.background||e.style.backgroundColor;if(bg&&!bg.startsWith('var('))e.style.background='var(--soft)';if(e.style.color&&!e.style.color.startsWith('var('))e.style.color='var(--ink)'});const tab=document.body.dataset.activeTab||'plan';document.querySelectorAll('#app-bottom-nav [data-app-tab]').forEach(e=>{if(e.dataset.appTab===tab)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current')})}sync();new MutationObserver(sync).observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['class']});runWrongAnswerCue=function(el){if(state.feedbackPreferences?.wrongAnswerFeedbackEnabled&&!matchMedia('(prefers-reduced-motion:reduce)').matches&&el?.animate)el.animate([{outlineColor:'#b78e88'},{outlineColor:'transparent'}],{duration:300})};const old=window.handleAction;window.handleAction=function(...a){try{return old(...a)}finally{sync()}}}document.addEventListener('DOMContentLoaded',init)})();